using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "LunarAlignmentCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/LunarAlignmentCustomDescription", order = 0)]
public class LunarAlignmentCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string arg = (battleAction as LunarAlignmentAction).PurifyAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).RemoveLast();
		string localizedForEach = base.localizationManager.GetLocalizedForEach();
		return Smart.Format(GetRawLocalizedDescription(battleAction), Smart.Format(localizedForEach.Replace(" {1}", "").Replace("{1}", ""), arg));
	}
}
